// words: exact exact
// input: u32
// output: u32
// overflow checks: on
#![cfg_attr(not(cpu_reference), no_std)]
#![allow(unused_mut, unused_variables, unused_assignments, unused_parens, unused_labels, unused_braces, unused_comparisons, unused_imports, dead_code, unreachable_code, arithmetic_overflow, unconditional_panic)]

#[derive(Clone, Copy)]
struct R0 { f0: [u16; 1], f1: i16, f2: Result<u64, u32> }

fn run(input: u32) -> [u32; 2] {
    let mut l21: u16 = (input as u16);
    let mut l28: R0 = R0 { f0: [l21], f1: 0_i16, f2: Err::<u64, u32>(input) };
    [(l21.rotate_left((l28.f0[(0_u64 as usize) % 1] as u32)) as u32), (input as u32)]
}

#[cfg(not(cpu_reference))]
use metal_oxide_device::{ReadBuffer, WriteBuffer, block_dim, block_idx, kernel, thread_idx};

#[cfg(not(cpu_reference))]
#[kernel]
pub unsafe fn generated(input: ReadBuffer<u32>, output: WriteBuffer<u32>, n: u32) {
    let i = block_idx().x * block_dim().x + thread_idx().x;
    if i < n {
        let words = run(unsafe { input.load_unchecked(i) });
        unsafe {
        output.store_unchecked(i * 2 + 0, words[0]);
        output.store_unchecked(i * 2 + 1, words[1]);
        }
    }
}

